boolean isCircular(ListNode head) {
    Set<ListNode> seen = new HashSet<>();
    for (ListNode curr = head; curr != null; curr = curr.next) {
        if (seen.contains(curr)) return curr == head;   // the first node seen twice decides it
        seen.add(curr);
    }
    return false;                                       // reached null: the list has an end
}

bool isCircular(ListNode* head) {
    unordered_set<ListNode*> seen;
    for (ListNode* curr = head; curr != nullptr; curr = curr->next) {
        if (seen.count(curr)) return curr == head;      // the first node seen twice decides it
        seen.insert(curr);
    }
    return false;                                       // reached null: the list has an end
}

function isCircular(head) {
  if (head === null) return false;     // an empty list has no ring
  let curr = head.next;
  while (curr !== null && curr !== head) curr = curr.next;   // until the end, or back at the start
  return curr === head;                // back at the head: circular; fell off at null: not
}

boolean isCircular(ListNode head) {
    if (head == null) return false;      // an empty list has no ring
    ListNode curr = head.next;
    while (curr != null && curr != head) curr = curr.next;   // until the end, or back at the start
    return curr == head;                 // back at the head: circular; fell off at null: not
}

